#!/usr/bin/env python3
# SPDX-FileCopyrightText: 2026 Hitesh Soliwal and Contributors to the Synexia Project
# SPDX-License-Identifier: Apache-2.0

"""Manage Synexia's bounded active GitHub Actions control plane."""

from __future__ import annotations

import argparse
import csv
import hashlib
import shutil
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
ACTIVE = ROOT / ".github" / "workflows"
CATALOG = ROOT / ".github" / "workflow-catalog"
MANIFEST = CATALOG / "M3_WORKFLOW_CATALOG.tsv"
DEFAULT_MAX_ACTIVE = 32


def workflow_files(root: Path) -> list[Path]:
    if not root.is_dir():
        return []
    return sorted(
        p for p in root.iterdir()
        if p.is_file() and p.suffix.lower() in {".yml", ".yaml"}
    )


def git_blob_sha(path: Path) -> str:
    data = path.read_bytes()
    header = f"blob {len(data)}\0".encode("ascii")
    return hashlib.sha1(header + data).hexdigest()


def read_manifest() -> dict[str, dict[str, str]]:
    rows: dict[str, dict[str, str]] = {}
    with MANIFEST.open("r", encoding="utf-8", newline="") as fh:
        data = [line for line in fh if line.strip() and not line.startswith("#")]
    reader = csv.DictReader(data, delimiter="\t")
    required = {
        "name", "disposition", "originalPath", "currentPath", "blobSha", "size"
    }
    if reader.fieldnames is None or set(reader.fieldnames) != required:
        raise ValueError("invalid workflow catalog manifest columns")
    for row in reader:
        name = row["name"]
        if not name or "/" in name or "\\" in name:
            raise ValueError(f"invalid workflow name: {name!r}")
        if name in rows:
            raise ValueError(f"duplicate workflow manifest row: {name}")
        rows[name] = row
    return rows


def write_manifest(rows: dict[str, dict[str, str]]) -> None:
    header = (
        "# SPDX-FileCopyrightText: 2026 Hitesh Soliwal and Contributors to the Synexia Project\n"
        "# SPDX-License-Identifier: Apache-2.0\n"
    )
    with MANIFEST.open("w", encoding="utf-8", newline="") as fh:
        fh.write(header)
        writer = csv.DictWriter(
            fh,
            fieldnames=[
                "name",
                "disposition",
                "originalPath",
                "currentPath",
                "blobSha",
                "size",
            ],
            delimiter="\t",
            lineterminator="\n",
        )
        writer.writeheader()
        for name in sorted(rows):
            writer.writerow(rows[name])


def set_disposition(
    rows: dict[str, dict[str, str]],
    name: str,
    disposition: str,
) -> None:
    if name not in rows:
        raise KeyError(f"workflow not present in manifest: {name}")
    if disposition not in {"ACTIVE", "DORMANT"}:
        raise ValueError(disposition)
    rows[name]["disposition"] = disposition
    rows[name]["currentPath"] = (
        f".github/workflows/{name}"
        if disposition == "ACTIVE"
        else f".github/workflow-catalog/{name}"
    )


def check(max_active: int) -> int:
    manifest = read_manifest()
    active = workflow_files(ACTIVE)
    dormant = workflow_files(CATALOG)
    active_names = {p.name for p in active}
    dormant_names = {p.name for p in dormant}
    errors: list[str] = []

    if len(active) > max_active:
        errors.append(
            f"active workflow count {len(active)} exceeds ceiling {max_active}"
        )

    overlap = sorted(active_names & dormant_names)
    if overlap:
        errors.append("active/catalog duplicates: " + ", ".join(overlap))

    tracked = active_names | dormant_names
    manifest_names = set(manifest)
    missing = sorted(manifest_names - tracked)
    untracked = sorted(tracked - manifest_names)
    if missing:
        errors.append("manifest workflows missing from both planes: " + ", ".join(missing))
    if untracked:
        errors.append("workflow files missing from manifest: " + ", ".join(untracked))

    for name, row in manifest.items():
        actual = (
            "ACTIVE" if name in active_names
            else "DORMANT" if name in dormant_names
            else "MISSING"
        )
        if actual == "MISSING":
            continue
        expected_path = (
            f".github/workflows/{name}"
            if actual == "ACTIVE"
            else f".github/workflow-catalog/{name}"
        )
        if row["disposition"] != actual:
            errors.append(
                f"{name}: manifest disposition={row['disposition']} actual={actual}"
            )
        if row["currentPath"] != expected_path:
            errors.append(
                f"{name}: manifest currentPath={row['currentPath']} expected={expected_path}"
            )
        current_file = ACTIVE / name if actual == "ACTIVE" else CATALOG / name
        actual_sha = git_blob_sha(current_file)
        if actual_sha != row["blobSha"]:
            errors.append(
                f"CONTENT_SHA_MISMATCH {name}: manifest={row['blobSha']} actual={actual_sha}"
            )

    if errors:
        for error in errors:
            print(f"ERROR: {error}", file=sys.stderr)
        return 1

    print(
        f"M3 workflow control plane PASS: active={len(active)} "
        f"dormant={len(dormant)} max_active={max_active}"
    )
    return 0


def move_one(name: str, source: Path, destination: Path) -> None:
    if "/" in name or "\\" in name or name in {"", ".", ".."}:
        raise ValueError(f"invalid workflow name: {name!r}")
    src = source / name
    dst = destination / name
    if not src.is_file():
        raise FileNotFoundError(src)
    if dst.exists():
        raise FileExistsError(dst)
    destination.mkdir(parents=True, exist_ok=True)
    shutil.move(str(src), str(dst))


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest="command", required=True)

    c = sub.add_parser("check")
    c.add_argument("--max-active", type=int, default=DEFAULT_MAX_ACTIVE)

    a = sub.add_parser("activate")
    a.add_argument("names", nargs="+")

    p = sub.add_parser("park")
    p.add_argument("names", nargs="+")

    args = parser.parse_args()
    if args.command == "check":
        return check(args.max_active)

    if args.command == "activate":
        rows = read_manifest()
        for name in args.names:
            move_one(name, CATALOG, ACTIVE)
            set_disposition(rows, name, "ACTIVE")
        write_manifest(rows)
        return check(DEFAULT_MAX_ACTIVE)

    if args.command == "park":
        rows = read_manifest()
        for name in args.names:
            move_one(name, ACTIVE, CATALOG)
            set_disposition(rows, name, "DORMANT")
        write_manifest(rows)
        return check(DEFAULT_MAX_ACTIVE)

    raise AssertionError(args.command)


if __name__ == "__main__":
    raise SystemExit(main())
